VALUES
  ('59ddb399-d7b5-5028-9c23-10e0266cc3fa', 'arm_raise', '腕上げ', 'muscle_strength', 'upper_limb', 10, 'reps', 2, '椅子に座り、両腕を前から頭の高さまでゆっくり上げて下ろす。肩に痛みが出ない範囲で行う。', NOW() AT TIME ZONE 'UTC', NOW() AT TIME ZONE 'UTC'),
  ('2695a3cc-55d6-56a7-9081-c0d5a8deb450', 'wall_push_up', '壁押し', 'muscle_strength', 'upper_limb', 10, 'reps', 3, '壁から一歩離れて立ち、肩幅で壁に手をつく。肘をゆっくり曲げて胸を壁に近づけ、押し戻す。', NOW() AT TIME ZONE 'UTC', NOW() AT TIME ZONE 'UTC'),
