  ('f763a9de-9f16-5280-ac32-cc74381b80f3', 'push_up', '腕立て伏せ', 'muscle_strength', 'upper_limb', 10, 'reps', 3, 'つま先と手で体を支え、体を一直線に保ったまま肘を曲げて胸を床に近づけ、押し戻す。', NOW() AT TIME ZONE 'UTC', NOW() AT TIME ZONE 'UTC'),
  ('bd995d96-1474-5569-8b07-8bb91215aa44', 'feet_elevated_push_up', '足上げ腕立て伏せ', 'muscle_strength', 'upper_limb', 8, 'reps', 3, '両足を椅子や台に乗せて腕立て伏せを行う。腰が反らないように腹に力を入れる。', NOW() AT TIME ZONE 'UTC', NOW() AT TIME ZONE 'UTC'),
  ('d652e3bb-859b-5bba-88e8-8dc6b397126e', 'assisted_sit_to_stand', '支えあり立ち座り', 'muscle_strength', 'lower_limb', 5, 'reps', 2, '椅子に浅く座り、机や手すりに手を添えてゆっくり立ち上がり、ゆっくり座る。', NOW() AT TIME ZONE 'UTC', NOW() AT TIME ZONE 'UTC'),
  ('542b0651-be9a-558b-87ba-c47c2e3f13f0', 'chair_squat', '椅子スクワット', 'muscle_strength', 'lower_limb', 10, 'reps', 3, '椅子の前に立ち、お尻を後ろに引いて座面に触れる直前まで腰を落とし、立ち上がる。', NOW() AT TIME ZONE 'UTC', NOW() AT TIME ZONE 'UTC'),
  ('60da87f0-3f50-5c42-8801-0313a3be3e38', 'squat', 'スクワット', 'muscle_strength', 'lower_limb', 10, 'reps', 3, '足を肩幅に開き、膝がつま先より前に出ないように腰を落とす。太ももが床と平行になる手前まで下げる。', NOW() AT TIME ZONE 'UTC', NOW() AT TIME ZONE 'UTC'),
