  ('cca00767-2835-5336-b3f7-812c8544003b', 'supine_bridge', '仰向けブリッジ', 'muscle_strength', 'whole_body', 10, 'reps', 2, '仰向けで膝を立て、お尻を持ち上げて数秒保ち、ゆっくり下ろす。', NOW() AT TIME ZONE 'UTC', NOW() AT TIME ZONE 'UTC'),
